#[Route('/products', methods: ['POST'])]
public function create(
    Request $r,
    EntityManagerInterface $em,
): JsonResponse {
    $p = new Product($r->request->getString('name'));
    $em->persist($p);
    $em->flush(); // runs the INSERT
    return $this->json(['id' => $p->getId()], 201);
}
